jobs := make(chan Job, 1000)              // the bound: a full channel blocks the sender
for i := 0; i < runtime.NumCPU(); i++ {
    go func() {
        for j := range jobs {            // workers drain at their own pace
            process(j)
        }
    }()
}
for _, j := range requests {
    jobs <- j                            // paced, not dropped
}
close(jobs)                              // ends the consumer loops
